"""Writes src/export/export-schema.ts from the C# Core/JsonExport.cs (itself generated by the C# repo's
scripts/gen-json-export.py): for every record type, its exported keys in order with how each value is written.

Run from the repo root: python scripts/gen-json-export.py [path to JsonExport.cs]
"""
import re
import sys
from pathlib import Path

source = Path(sys.argv[1] if len(sys.argv) > 1 else
              '../UniverseGenerator/Packages/com.m4bwav.universe-generator/Runtime/Core/JsonExport.cs').read_text(encoding='utf-8')
source = source.replace('\r\n', '\n')

fields = re.findall(r'private static void Fields\(JsonWriter w, (\w+) v, bool children\)\n        \{\n(.*?)\n        \}\n', source, re.S)
tops = re.findall(r'public static void Write\(JsonWriter w, (\w+) v, bool children, string type\)', source)
runtime = Path(sys.argv[1]).parent.parent if len(sys.argv) > 1 else Path('../UniverseGenerator/Packages/com.m4bwav.universe-generator/Runtime')
# The type of every init property, by record: a child object's or list item's writer is the one for that type.
props = {}
for cs in runtime.rglob('*.cs'):
    record = None
    for line in cs.read_text(encoding='utf-8').splitlines():
        m = re.search(r'\b(?:record|class) (\w+)', line)
        if m and not line.strip().startswith('//'):
            record = m.group(1)
        m = re.search(r'public ([\w<>?, ()]+?) (\w+) \{ get; init; \}', line)
        if m and record:
            t = m.group(1)
            lm = re.match(r'IReadOnlyList<(\w+)\??>', t)
            props[(record, m.group(2))] = lm.group(1) if lm else t.rstrip('?')


def kind(body):
    """The way one key's value is written, from the C# statements after w.Name."""
    b = body.strip()
    if b.startswith('Real(w, v.'):
        return "'real'"
    if re.fullmatch(r'w\.Int\(v\.\w+\);', b):
        return "'int'"
    if re.fullmatch(r'w\.Bool\(v\.\w+\);', b):
        return "'bool'"
    if re.fullmatch(r'w\.String\(v\.\w+\);', b) or re.fullmatch(r'w\.String\(v\.\w+\.ToString\(\)\);', b):
        return "'string'"
    if b.startswith('Strings(w, v.'):
        return "'custom'"
    m = re.fullmatch(r'Write\(w, v\.(\w+), children\);', b)
    if m:
        return None  # resolved by the caller with the property type
    if b.startswith('if (children)'):
        return "'lazy'"
    if b.startswith('if (v.'):
        inner = b.split('else', 1)[1]
        if 'w.Int(' in inner:
            return "'int?'"
        if 'w.String(' in inner:
            return "'string?'"
        if 'Real(' in inner:
            return "'real?'"
        return "'object?'"
    if b.startswith('w.BeginArray();'):
        if 'w.String(item' in b:
            return "'strings'"
        if 'w.Int(item' in b:
            return "'ints'"
        return "'list'"
    raise SystemExit('unknown shape: ' + b)


out = []
for type_name, body in fields:
    parts = re.split(r'\n            w\.Name\("(\w+)"\);\n', '\n' + body.replace('            _ = children;\n', '').replace('            _ = children;', ''))
    entries = []
    for i in range(1, len(parts), 2):
        key = parts[i]
        k = kind(parts[i + 1]) or "'object'"
        prop = key[0].upper() + key[1:]
        if k in ("'object'", "'object?'", "'list'", "'lazy'"):
            sub = props.get((type_name, prop))
            if sub is None:
                raise SystemExit(f'no property type for {type_name}.{prop}')
            entries.append(f"['{key}', {k}, '{sub}']")
        else:
            entries.append(f"['{key}', {k}]")
    out.append(f'  {type_name}: [{", ".join(entries)}],')

text = ('// Generated by scripts/gen-json-export.py from the C# Core/JsonExport.cs; do not edit by hand.\n'
        '// For every record type, its exported keys in the C# order and how each value is written.\n'
        'export const exportFields = {\n' + '\n'.join(out) + '\n} as const;\n')
Path('src/export/export-schema.ts').parent.mkdir(exist_ok=True)
Path('src/export/export-schema.ts').write_bytes(text.encode('utf-8'))
print(len(fields), 'types;', 'top-level:', tops)
